-- P14 Morocco tax engine. Non-production DEMO defaults require accountant validation before production use.

create table public.tax_jurisdictions(
 code text primary key check(code~'^[A-Z]{2}$'),name_fr text not null,name_ar text not null,currency char(3)not null check(currency~'^[A-Z]{3}$'),status text not null check(status in('ACTIVE','RETIRED')),created_at timestamptz not null default clock_timestamp()
);
create table public.tax_categories(
 code text primary key check(code~'^[A-Z][A-Z0-9_]{2,79}$'),name_fr text not null check(length(btrim(name_fr))between 2 and 160),name_ar text not null check(length(btrim(name_ar))between 2 and 160),description_fr text not null,description_ar text not null,category_kind text not null check(category_kind in('SERVICE','FEE','DISTRIBUTION','PENALTY','CREDIT_NOTE')),requires_source_rule boolean not null default false,status text not null check(status in('ACTIVE','RETIRED')),created_at timestamptz not null default clock_timestamp()
);
alter table public.tax_rule_versions
 add column rule_type text not null default'VAT'check(rule_type in('VAT','EXEMPT','OUT_OF_SCOPE','WITHHOLDING')),
 add column priority integer not null default 100 check(priority between 1 and 10000),
 add column conditions jsonb not null default'{}'check(jsonb_typeof(conditions)='object'),
 add column legal_reference text not null default'NON_PRODUCTION_DEMO_REQUIRES_ACCOUNTANT_VALIDATION'check(length(btrim(legal_reference))between 10 and 1000),
 add column rounding_strategy text not null default'HALF_AWAY_FROM_ZERO_TO_MINOR_UNIT'check(rounding_strategy='HALF_AWAY_FROM_ZERO_TO_MINOR_UNIT'),
 add column approved_by uuid references auth.users(id),
 add column approved_at timestamptz,
 add column validation_reference text,
 add column content_hash text not null default repeat('0',64)check(content_hash~'^[0-9a-f]{64}$'),
 add column change_reason text not null default'Legacy version imported for review'check(length(btrim(change_reason))between 10 and 1000),
 add column row_version integer not null default 1 check(row_version>0),
 add constraint tax_rules_jurisdiction_fk foreign key(jurisdiction_code)references public.tax_jurisdictions(code)on delete restrict,
 add constraint tax_rules_category_fk foreign key(category_code)references public.tax_categories(code)on delete restrict,
 add constraint tax_rules_active_validation_check check(status<>'ACTIVE'or professional_validation_status in('DEMO','VALIDATED')),
 add constraint tax_rules_validated_approval_check check(professional_validation_status<>'VALIDATED'or(approved_by is not null and approved_at is not null and validation_reference is not null and length(btrim(validation_reference))>=3));
alter table public.tax_rule_versions alter column rule_type drop default,alter column priority drop default,alter column conditions drop default,alter column legal_reference drop default,alter column rounding_strategy drop default,alter column content_hash drop default,alter column change_reason drop default;
alter table public.tax_rule_versions add constraint tax_rules_no_active_period_overlap exclude using gist(jurisdiction_code with=,category_code with=,daterange(effective_from,effective_to,'[]')with&&)where(status='ACTIVE');

create table public.tax_rule_validation_events(
 id bigint generated always as identity primary key,tax_rule_version_id uuid not null references public.tax_rule_versions(id)on delete restrict,decision text not null check(decision in('APPROVE','REJECT','RETIRE')),professional_validation_status text not null check(professional_validation_status in('DEMO','VALIDATED')),validation_reference text not null check(length(btrim(validation_reference))between 3 and 500),reason text not null check(length(btrim(reason))between 10 and 1000),rule_content_hash text not null check(rule_content_hash~'^[0-9a-f]{64}$'),decided_by uuid not null references auth.users(id),correlation_id uuid not null,decided_at timestamptz not null default clock_timestamp()
);

create function private.prevent_tax_reference_change()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception 'IMMUTABLE_TAX_REFERENCE'using errcode='55000';end$$;
create function private.guard_tax_rule_version()returns trigger language plpgsql set search_path=pg_catalog as $$begin if tg_op='DELETE'or row(old.jurisdiction_code,old.category_code,old.version,old.rate_basis_points,old.effective_from,old.effective_to,old.rule_type,old.priority,old.conditions,old.legal_reference,old.rounding_strategy,old.content_hash,old.change_reason,old.created_by,old.created_at)is distinct from row(new.jurisdiction_code,new.category_code,new.version,new.rate_basis_points,new.effective_from,new.effective_to,new.rule_type,new.priority,new.conditions,new.legal_reference,new.rounding_strategy,new.content_hash,new.change_reason,new.created_by,new.created_at)or(old.status='RETIRED'and new.status<>'RETIRED')or(old.status='ACTIVE'and new.status='DRAFT')then raise exception 'IMMUTABLE_TAX_RULE_CONTENT'using errcode='55000';end if;return new;end$$;
create trigger tax_jurisdictions_immutable before update or delete on public.tax_jurisdictions for each row execute function private.prevent_tax_reference_change();
create trigger tax_categories_immutable before update or delete on public.tax_categories for each row execute function private.prevent_tax_reference_change();
create trigger tax_rule_versions_content_immutable before update or delete on public.tax_rule_versions for each row execute function private.guard_tax_rule_version();
create trigger tax_rule_validation_events_immutable before update or delete on public.tax_rule_validation_events for each row execute function private.prevent_tax_reference_change();

create function private.morocco_tax_admin(p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select p_actor is not null and p_actor=auth.uid()and private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER'],p_actor)and coalesce(auth.jwt()->>'aal','')='aal2'$$;
create function private.calculate_tax_minor(p_net_minor bigint,p_rate_basis_points integer)returns bigint language sql immutable strict set search_path=pg_catalog as $$select case when p_net_minor<0 then-floor((abs(p_net_minor)::numeric*p_rate_basis_points+5000)/10000)::bigint else floor((p_net_minor::numeric*p_rate_basis_points+5000)/10000)::bigint end$$;
create function private.resolve_morocco_tax(p_category_code text,p_effective_on date,p_net_minor bigint,p_source_rule_version_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$declare c public.tax_categories%rowtype;r public.tax_rule_versions%rowtype;tax bigint;begin if p_effective_on is null or p_net_minor=0 then raise exception 'INVALID_TAX_SIMULATION_INPUT'using errcode='22023';end if;select * into c from public.tax_categories where code=p_category_code and status='ACTIVE';if not found then raise exception 'TAX_CATEGORY_NOT_FOUND'using errcode='P0002';end if;if c.category_kind='CREDIT_NOTE'then if p_net_minor>=0 or p_source_rule_version_id is null then raise exception 'CREDIT_NOTE_SOURCE_RULE_REQUIRED'using errcode='22023';end if;select * into r from public.tax_rule_versions where id=p_source_rule_version_id and jurisdiction_code='MA'and status in('ACTIVE','RETIRED')and effective_from<=p_effective_on and(effective_to is null or effective_to>=p_effective_on);else if p_net_minor<0 then raise exception 'NEGATIVE_NET_REQUIRES_CREDIT_NOTE'using errcode='22023';end if;select * into r from public.tax_rule_versions where jurisdiction_code='MA'and category_code=p_category_code and status='ACTIVE'and effective_from<=p_effective_on and(effective_to is null or effective_to>=p_effective_on)and professional_validation_status in('DEMO','VALIDATED')order by priority,version desc limit 1;end if;if r.id is null then raise exception 'MOROCCO_TAX_RULE_NOT_FOUND'using errcode='P0002';end if;tax:=case when r.rule_type in('EXEMPT','OUT_OF_SCOPE')then 0 else private.calculate_tax_minor(p_net_minor,r.rate_basis_points)end;return jsonb_build_object('jurisdiction_code','MA','category_code',p_category_code,'effective_on',p_effective_on,'tax_rule_version_id',r.id,'tax_rule_version',r.version,'professional_validation_status',r.professional_validation_status,'rule_type',r.rule_type,'line_net_minor',p_net_minor::text,'tax_rate_basis_points',r.rate_basis_points,'tax_amount_minor',tax::text,'line_gross_minor',(p_net_minor+tax)::text,'rounding_strategy',r.rounding_strategy,'legal_reference',r.legal_reference);end$$;

create function public.list_morocco_tax_rules()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$declare a uuid:=auth.uid();begin if not private.morocco_tax_admin(a)then raise exception 'MOROCCO_TAX_ADMIN_AAL2_REQUIRED'using errcode='42501';end if;return jsonb_build_object('jurisdiction',(select to_jsonb(j)from public.tax_jurisdictions j where code='MA'),'categories',coalesce((select jsonb_agg(to_jsonb(c)order by c.code)from public.tax_categories c),'[]'),'rules',coalesce((select jsonb_agg(to_jsonb(r)order by r.category_code,r.version desc)from public.tax_rule_versions r where r.jurisdiction_code='MA'),'[]'));end$$;
create function public.simulate_morocco_tax(p_category_code text,p_effective_on date,p_net_minor bigint,p_source_rule_version_id uuid default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$declare a uuid:=auth.uid();begin if not private.morocco_tax_admin(a)then raise exception 'MOROCCO_TAX_SIMULATION_AAL2_REQUIRED'using errcode='42501';end if;return private.resolve_morocco_tax(p_category_code,p_effective_on,p_net_minor,p_source_rule_version_id);end$$;

create function public.propose_morocco_tax_rule(p_audit_organization_id uuid,p_category_code text,p_rule_type text,p_rate_basis_points integer,p_priority integer,p_conditions jsonb,p_legal_reference text,p_effective_from date,p_effective_to date,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();v integer;rid uuid;request_hash text;content_hash text;r jsonb;begin if not private.morocco_tax_admin(a)or not private.is_active_org_member(p_audit_organization_id,a)then raise exception 'MOROCCO_TAX_PROPOSAL_DENIED'using errcode='42501';end if;if not exists(select 1 from public.tax_categories where code=p_category_code and status='ACTIVE')or p_rule_type not in('VAT','EXEMPT','OUT_OF_SCOPE','WITHHOLDING')or p_rate_basis_points not between 0 and 10000 or p_priority not between 1 and 10000 or jsonb_typeof(p_conditions)<>'object'or length(btrim(coalesce(p_legal_reference,'')))not between 10 and 1000 or p_effective_from is null or(p_effective_to is not null and p_effective_to<p_effective_from)or length(btrim(coalesce(p_change_reason,'')))not between 10 and 1000 or(p_rule_type in('EXEMPT','OUT_OF_SCOPE')and p_rate_basis_points<>0)then raise exception 'INVALID_MOROCCO_TAX_RULE'using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended('MA:'||p_category_code,0));request_hash:=private.canonical_request_hash(jsonb_build_object('jurisdiction','MA','category',p_category_code,'type',p_rule_type,'rate_bps',p_rate_basis_points,'priority',p_priority,'conditions',p_conditions,'legal_reference',p_legal_reference,'from',p_effective_from,'to',p_effective_to,'reason',btrim(p_change_reason)));r:=private.begin_contract_command(p_audit_organization_id,'morocco.tax.rule.propose.'||p_category_code,p_idempotency_key,request_hash,a);if r is not null then return r;end if;select coalesce(max(version),0)+1 into v from public.tax_rule_versions where jurisdiction_code='MA'and category_code=p_category_code;content_hash:=private.canonical_request_hash(jsonb_build_object('request_hash',request_hash,'version',v));insert into public.tax_rule_versions(jurisdiction_code,category_code,version,rate_basis_points,effective_from,effective_to,status,professional_validation_status,created_by,rule_type,priority,conditions,legal_reference,rounding_strategy,content_hash,change_reason)values('MA',p_category_code,v,p_rate_basis_points,p_effective_from,p_effective_to,'DRAFT','PENDING',a,p_rule_type,p_priority,p_conditions,btrim(p_legal_reference),'HALF_AWAY_FROM_ZERO_TO_MINOR_UNIT',content_hash,btrim(p_change_reason))returning id into rid;r:=jsonb_build_object('outcome','MOROCCO_TAX_RULE_PROPOSED','tax_rule_version_id',rid,'version',v,'content_hash',content_hash);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_audit_organization_id,a,'USER','morocco.tax_rule.proposed','tax_rule_version',rid::text,p_correlation_id,jsonb_build_object('category_code',p_category_code,'version',v,'content_hash',content_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_audit_organization_id,'tax_rule_version',rid::text,'MoroccoTaxRuleProposedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_audit_organization_id,'morocco.tax.rule.propose.'||p_category_code,p_idempotency_key,r);return r;end$$;

create function public.decide_morocco_tax_rule(p_audit_organization_id uuid,p_tax_rule_version_id uuid,p_decision text,p_professional_validation_status text,p_validation_reference text,p_reason text,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();x public.tax_rule_versions%rowtype;h text;r jsonb;target text;begin select * into x from public.tax_rule_versions where id=p_tax_rule_version_id for update;if not private.morocco_tax_admin(a)or not private.is_active_org_member(p_audit_organization_id,a)or x.id is null or a=x.created_by then raise exception 'MOROCCO_TAX_DECISION_DENIED'using errcode='42501';end if;if p_decision not in('APPROVE','REJECT','RETIRE')or p_professional_validation_status not in('DEMO','VALIDATED')or length(btrim(coalesce(p_validation_reference,'')))not between 3 and 500 or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception 'INVALID_MOROCCO_TAX_DECISION'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('rule_id',x.id,'decision',p_decision,'validation_status',p_professional_validation_status,'validation_reference',p_validation_reference,'reason',p_reason,'expected',p_expected_row_version,'content_hash',x.content_hash));r:=private.begin_contract_command(p_audit_organization_id,'morocco.tax.rule.decide.'||x.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;if(p_decision in('APPROVE','REJECT')and x.status<>'DRAFT')or(p_decision='RETIRE'and x.status<>'ACTIVE')then raise exception 'INVALID_MOROCCO_TAX_LIFECYCLE'using errcode='55000';end if;if x.row_version<>p_expected_row_version then raise exception 'STALE_MOROCCO_TAX_RULE'using errcode='40001';end if;target:=case when p_decision='APPROVE'then'ACTIVE'else'RETIRED'end;update public.tax_rule_versions set status=target,professional_validation_status=p_professional_validation_status,approved_by=a,approved_at=clock_timestamp(),validation_reference=btrim(p_validation_reference),row_version=row_version+1 where id=x.id;insert into public.tax_rule_validation_events(tax_rule_version_id,decision,professional_validation_status,validation_reference,reason,rule_content_hash,decided_by,correlation_id)values(x.id,p_decision,p_professional_validation_status,btrim(p_validation_reference),btrim(p_reason),x.content_hash,a,p_correlation_id);r:=jsonb_build_object('outcome',case p_decision when'APPROVE'then'MOROCCO_TAX_RULE_ACTIVATED'when'RETIRE'then'MOROCCO_TAX_RULE_RETIRED'else'MOROCCO_TAX_RULE_REJECTED'end,'tax_rule_version_id',x.id,'status',target,'row_version',x.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_audit_organization_id,a,'USER','morocco.tax_rule.decided','tax_rule_version',x.id::text,p_correlation_id,jsonb_build_object('decision',p_decision,'validation_status',p_professional_validation_status,'validation_reference',p_validation_reference,'reason',p_reason,'content_hash',x.content_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_audit_organization_id,'tax_rule_version',x.id::text,case p_decision when'APPROVE'then'MoroccoTaxRuleActivatedV1'when'RETIRE'then'MoroccoTaxRuleRetiredV1'else'MoroccoTaxRuleRejectedV1'end,p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_audit_organization_id,'morocco.tax.rule.decide.'||x.id::text,p_idempotency_key,r);return r;end$$;

alter table public.tax_jurisdictions enable row level security;alter table public.tax_categories enable row level security;alter table public.tax_rule_validation_events enable row level security;
drop policy if exists active_tax_rules_authenticated_read on public.tax_rule_versions;
create policy tax_jurisdictions_active_read on public.tax_jurisdictions for select to authenticated using(status='ACTIVE');create policy tax_categories_active_read on public.tax_categories for select to authenticated using(status='ACTIVE');create policy tax_rules_active_read on public.tax_rule_versions for select to authenticated using(status='ACTIVE');create policy tax_validation_admin_read on public.tax_rule_validation_events for select to authenticated using(private.morocco_tax_admin());
revoke all on public.tax_jurisdictions,public.tax_categories,public.tax_rule_validation_events,public.tax_rule_versions from public,anon,authenticated,service_role;grant select on public.tax_jurisdictions,public.tax_categories,public.tax_rule_validation_events,public.tax_rule_versions to authenticated;
revoke all on function private.prevent_tax_reference_change(),private.guard_tax_rule_version(),private.morocco_tax_admin(uuid),private.calculate_tax_minor(bigint,integer),private.resolve_morocco_tax(text,date,bigint,uuid)from public,anon,authenticated,service_role;grant execute on function private.morocco_tax_admin(uuid)to authenticated;
revoke all on function public.list_morocco_tax_rules(),public.simulate_morocco_tax(text,date,bigint,uuid),public.propose_morocco_tax_rule(uuid,text,text,integer,integer,jsonb,text,date,date,text,text,uuid),public.decide_morocco_tax_rule(uuid,uuid,text,text,text,text,integer,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.list_morocco_tax_rules(),public.simulate_morocco_tax(text,date,bigint,uuid),public.propose_morocco_tax_rule(uuid,text,text,integer,integer,jsonb,text,date,date,text,text,uuid),public.decide_morocco_tax_rule(uuid,uuid,text,text,text,text,integer,text,uuid)to authenticated;
create index tax_rules_admin_history_idx on public.tax_rule_versions(jurisdiction_code,category_code,version desc);create index tax_validation_rule_idx on public.tax_rule_validation_events(tax_rule_version_id,decided_at desc);

